import React, { useState } from 'react';

export default function ConnectionForm({ onSubmit, loading }) {
  const [connStr, setConnStr] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    if (connStr.trim()) onSubmit(connStr.trim());
  };

  return (
    <div style={styles.wrapper}>
      <div style={styles.card}>
        <div style={styles.iconWrap}>
          <span style={styles.icon}>⚡</span>
        </div>
        <h1 style={styles.heading}>AI Dashboard Generator</h1>
        <p style={styles.sub}>
          Connect your PostgreSQL database and let AI generate business insights with interactive charts.
        </p>

        <form onSubmit={handleSubmit} style={styles.form}>
          <label style={styles.label}>PostgreSQL Connection String</label>
          <input
            type="text"
            value={connStr}
            onChange={(e) => setConnStr(e.target.value)}
            placeholder="postgresql://user:password@localhost:5432/mydb"
            style={styles.input}
            disabled={loading}
            autoComplete="off"
            spellCheck={false}
          />
          <p style={styles.hint}>
            Your connection string is never stored — it is used only to read schema and run SELECT queries.
          </p>
          <button
            type="submit"
            disabled={loading || !connStr.trim()}
            style={{
              ...styles.button,
              ...(loading || !connStr.trim() ? styles.buttonDisabled : {}),
            }}
          >
            {loading ? (
              <span style={styles.btnContent}>
                <span style={styles.spinner} /> Analyzing Database...
              </span>
            ) : (
              '🚀 Generate Dashboard'
            )}
          </button>
        </form>

        <div style={styles.features}>
          {['Schema extraction', 'AI-powered insights', 'Live SQL execution', 'ECharts visualization'].map((f) => (
            <span key={f} style={styles.badge}>{f}</span>
          ))}
        </div>
      </div>
    </div>
  );
}

const styles = {
  wrapper: {
    minHeight: '100vh',
    background: 'linear-gradient(135deg, #0f0c29, #302b63, #24243e)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '20px',
  },
  card: {
    background: 'rgba(255,255,255,0.05)',
    backdropFilter: 'blur(20px)',
    border: '1px solid rgba(255,255,255,0.1)',
    borderRadius: '20px',
    padding: '48px',
    maxWidth: '560px',
    width: '100%',
    boxShadow: '0 25px 60px rgba(0,0,0,0.5)',
    textAlign: 'center',
  },
  iconWrap: { marginBottom: '16px' },
  icon: { fontSize: '48px' },
  heading: {
    fontSize: '28px',
    fontWeight: '700',
    color: '#fff',
    margin: '0 0 12px',
    letterSpacing: '-0.5px',
  },
  sub: {
    color: 'rgba(255,255,255,0.6)',
    fontSize: '15px',
    lineHeight: '1.6',
    margin: '0 0 32px',
  },
  form: { textAlign: 'left' },
  label: {
    display: 'block',
    color: 'rgba(255,255,255,0.8)',
    fontSize: '13px',
    fontWeight: '600',
    marginBottom: '8px',
    letterSpacing: '0.5px',
    textTransform: 'uppercase',
  },
  input: {
    width: '100%',
    padding: '14px 16px',
    background: 'rgba(255,255,255,0.08)',
    border: '1px solid rgba(255,255,255,0.2)',
    borderRadius: '10px',
    color: '#fff',
    fontSize: '14px',
    outline: 'none',
    fontFamily: 'monospace',
    boxSizing: 'border-box',
    transition: 'border-color 0.2s',
  },
  hint: {
    color: 'rgba(255,255,255,0.35)',
    fontSize: '12px',
    margin: '8px 0 24px',
    lineHeight: '1.5',
  },
  button: {
    width: '100%',
    padding: '15px',
    background: 'linear-gradient(135deg, #667eea, #764ba2)',
    color: '#fff',
    border: 'none',
    borderRadius: '10px',
    fontSize: '16px',
    fontWeight: '600',
    cursor: 'pointer',
    transition: 'opacity 0.2s, transform 0.1s',
    letterSpacing: '0.3px',
  },
  buttonDisabled: {
    opacity: 0.5,
    cursor: 'not-allowed',
  },
  btnContent: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '10px',
  },
  spinner: {
    display: 'inline-block',
    width: '16px',
    height: '16px',
    border: '2px solid rgba(255,255,255,0.3)',
    borderTopColor: '#fff',
    borderRadius: '50%',
    animation: 'spin 0.8s linear infinite',
  },
  features: {
    display: 'flex',
    flexWrap: 'wrap',
    gap: '8px',
    justifyContent: 'center',
    marginTop: '28px',
  },
  badge: {
    background: 'rgba(102,126,234,0.2)',
    border: '1px solid rgba(102,126,234,0.4)',
    color: 'rgba(255,255,255,0.7)',
    padding: '4px 12px',
    borderRadius: '20px',
    fontSize: '12px',
  },
};
